node --input-type=module -e '
import fs from "node:fs";
import crypto from "node:crypto";
import assert from "node:assert/strict";
import { createRequire } from "node:module";
import { artifactDigest, taskContractDigest } from "./scripts/remediation/board.mjs";
const require = createRequire(import.meta.url);
const { applyPatch } = require("diff");
const read = p => JSON.parse(fs.readFileSync(p, "utf8"));
const sha = v => crypto.createHash("sha256").update(v).digest("hex");
const dir = "docs/remediation/evidence/W12.01/";
const a=read(dir+"artifact.json"), w=read(dir+"worker.json"), b=read(dir+"baseline.json"), r=read(dir+"runtime-basis.json");
const c=read("docs/remediation/design/W12.01/task-contract-v1.json");
assert.equal(artifactDigest(a),a.digest);
assert.equal(taskContractDigest(c),a.contract_digest);
for(const f of a.files) assert.equal(sha(fs.readFileSync(f.path)),f.sha256,f.path);
for(const f of r.files) assert.ok(a.files.some(p=>p.path===f.path&&p.sha256===f.sha256),f.path);
const patches=[];
for(const p of w.implementation) {
 const old=b.files.find(f=>f.path===p.path);
 const current=fs.readFileSync(p.path,"utf8");
 assert.equal(sha(old.content),old.sha256);
 assert.equal(old.sha256,p.before_sha256);
 assert.equal(sha(current),p.final_sha256);
 assert.equal(sha(p.admission_patch),p.patch_sha256);
 assert.equal(applyPatch(old.content,p.admission_patch),current,p.path);
 patches.push(p.path);
}
const oldMonitor=b.files.find(f=>f.path==="src/ops/monitor.ts").content;
const monitor=fs.readFileSync("src/ops/monitor.ts","utf8");
assert.equal(monitor.slice(monitor.indexOf("export async function alert(")),oldMonitor.slice(oldMonitor.indexOf("export async function alert(")));
for(const phrase of ["try { env.ANALYTICS?.writeDataPoint", "console.log"]) {
 const line=s=>s.split("\n").find(l=>l.trimStart().startsWith(phrase));
 assert.equal(line(monitor),line(oldMonitor),phrase);
}
assert.equal(w.checks[0].command,c.checks[0].command);
assert.ok(w.checks.every(v=>v.exit_code===0&&v.attempt===1));
console.log(JSON.stringify({checked_at:new Date().toISOString(),artifact_digest:a.digest,contract_digest:a.contract_digest,pins:a.files.length,runtime_pins:r.files.length,patches,unchanged:"alert implementation and exact minimized AE/console expressions",worker_checks:w.checks.map(v=>({id:v.id,exit_code:v.exit_code})),artifact_file_sha256:sha(fs.readFileSync(dir+"artifact.json")),worker_sha256:sha(fs.readFileSync(dir+"worker.json"))},null,2));
'

